import{_ as n,o as a,c as t,ah as o}from"./chunks/framework.ojwJKwrc.js";const m=JSON.parse('{"title":"Compiler Components","description":"","frontmatter":{},"headers":[],"relativePath":"internals/compiler-crate-architecture.md","filePath":"internals/compiler-crate-architecture.md"}'),i={name:"internals/compiler-crate-architecture.md"};function s(r,e,c,d,l,p){return a(),t("div",null,[...e[0]||(e[0]=[o(`<h1 id="compiler-components" tabindex="-1">Compiler Components <a class="header-anchor" href="#compiler-components" aria-label="Permalink to &quot;Compiler Components&quot;">​</a></h1><p>Celox separates source-language analysis, simulator IR, target code generation, and runtime execution into crates with one-way dependencies. This page describes the current ownership boundaries. It is not a migration plan or a record of past refactors.</p><h2 id="pipeline" tabindex="-1">Pipeline <a class="header-anchor" href="#pipeline" aria-label="Permalink to &quot;Pipeline&quot;">​</a></h2><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>Veryl source</span></span>
<span class="line"><span>    │</span></span>
<span class="line"><span>    ▼</span></span>
<span class="line"><span>celox-frontend-veryl ──► SymbolicRtl ──► ScheduledRtl</span></span>
<span class="line"><span>          │                    │                │</span></span>
<span class="line"><span>          │              celox-slt              ▼</span></span>
<span class="line"><span>          │                              UnoptimizedSir</span></span>
<span class="line"><span>          │                                    │</span></span>
<span class="line"><span>          │                              celox-sir-opt</span></span>
<span class="line"><span>          │                                    ▼</span></span>
<span class="line"><span>          │                               OptimizedSir</span></span>
<span class="line"><span>          │                                    │</span></span>
<span class="line"><span>          │                           celox-state-layout</span></span>
<span class="line"><span>          │                                    ▼</span></span>
<span class="line"><span>          │                              LaidOutProgram</span></span>
<span class="line"><span>          │                                    │</span></span>
<span class="line"><span>          │                 ┌──────────────────┼──────────────────┐</span></span>
<span class="line"><span>          │                 ▼                  ▼                  ▼</span></span>
<span class="line"><span>          │          backend-x86      backend-cranelift    backend-wasm</span></span>
<span class="line"><span>          │                 └──────────────────┼──────────────────┘</span></span>
<span class="line"><span>          │                                    ▼</span></span>
<span class="line"><span>          └───────────────────────────── RuntimeProgram</span></span>
<span class="line"><span>                                               │</span></span>
<span class="line"><span>                                         celox-runtime</span></span></code></pre></div><p>The <code>celox</code> crate is the public facade and compiler driver. It wires these phases together, selects a backend, and exposes the simulator API. Lower-level crates do not depend on the facade. <code>celox-backend-x86</code> and <code>celox-backend-arm64</code> depend on <code>celox-backend-common</code> for allocation machinery; that crate is a compile-time library, not another pipeline artifact.</p><p><code>celox-backend-arm64</code> is wired into native backend selection behind the default-off <code>experimental-arm64-backend</code> feature and emits complete scalar simulation kernels. Its production path temporarily uses the established x86-owned scalar lowering and allocation pipeline as a compatibility bridge. The migration target is separate x86 and AArch64 MIR pipelines which export only opcode-free allocation facts to <code>celox-backend-common</code>.</p><h2 id="native-mir-and-allocation-boundary" tabindex="-1">Native MIR and allocation boundary <a class="header-anchor" href="#native-mir-and-allocation-boundary" aria-label="Permalink to &quot;Native MIR and allocation boundary&quot;">​</a></h2><p>Native backends do not share an instruction enum. Each target owns instruction selection, machine optimization, legalization, register classes, ABI rules, spill/reload construction, and post-allocation rewriting:</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>                         x86 instruction selection -&gt; X86 MIR -&gt; x86 passes</span></span>
<span class="line"><span>LaidOutProgram -&gt; SIR --&lt;                                           |</span></span>
<span class="line"><span>                         A64 instruction selection -&gt; A64 MIR -&gt; A64 passes</span></span>
<span class="line"><span>                                                                     |</span></span>
<span class="line"><span>                                      opcode-free allocation facts &lt;-+</span></span>
<span class="line"><span>                                                                     |</span></span>
<span class="line"><span>                                      shared allocation algorithms</span></span></code></pre></div><p>Immediately before a reusable allocation analysis, a backend projects its MIR into normalized facts: CFG successors, phi edges, virtual-register uses and definitions, fixed operands, clobbers, and copy hints. Shared code must consume these facts instead of matching target opcodes. Target drivers remain responsible for turning allocation decisions into legal machine instructions.</p><p>Optimizations which are genuinely independent of machine instruction shape belong in <code>celox-sir-opt</code>. DCE or CFG algorithms may be shared over allocation facts when their required semantics are fully represented, but common MIR opcodes must not be introduced merely to reuse a pass.</p><p>The facade&#39;s default <code>host-runtime</code> feature owns host execution, Cranelift, Wasmtime, the x86 backend, and the test macro. WebAssembly bindings disable that feature and depend only on the shared compiler plus <code>celox-backend-wasm</code>. Target checks therefore remain at the x86 selection boundary; shared compiler crates do not infer optimization or timing policy from the architecture they are compiled for.</p><h2 id="component-ownership" tabindex="-1">Component ownership <a class="header-anchor" href="#component-ownership" aria-label="Permalink to &quot;Component ownership&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Crate</th><th>Owns</th><th>Must not own</th></tr></thead><tbody><tr><td><code>celox-analysis</code></td><td>Reusable graph and data-flow algorithms</td><td>Veryl or backend-specific types</td></tr><tr><td><code>celox-design</code></td><td>Source-independent design identities, hierarchy, events, and runtime schema</td><td>Parser nodes or physical addresses</td></tr><tr><td><code>celox-frontend-veryl</code></td><td>Veryl analysis, source lookup, module construction, and frontend diagnostics</td><td>Optimization or target code generation</td></tr><tr><td><code>celox-slt</code></td><td>Symbolic logic trees, dependency scheduling, and SLT-to-SIR lowering</td><td>Veryl parser details or physical layout</td></tr><tr><td><code>celox-sir</code></td><td>Backend-independent simulator IR and control-flow structures</td><td>Target instructions or runtime scheduling</td></tr><tr><td><code>celox-sir-opt</code></td><td>Backend-independent SIR analyses and transformation passes</td><td>Veryl ASTs or target MIR</td></tr><tr><td><code>celox-state-layout</code></td><td>Semantic-to-physical state mapping and layout validation</td><td>Optimization policy or executable memory</td></tr><tr><td><code>celox-backend-common</code></td><td>Target-independent register sets, constraints, locations, and allocation mechanisms</td><td>Target registers, ABI rules, or instruction encodings</td></tr><tr><td><code>celox-backend-arm64</code></td><td>AArch64 MIR, register policy, AAPCS64 lowering, and machine-code emission</td><td>x86 constraints or frontend policy</td></tr><tr><td><code>celox-backend-x86</code></td><td>x86 MIR, instruction selection, target allocation policy, and machine-code emission</td><td>Frontend or runtime policy</td></tr><tr><td><code>celox-backend-cranelift</code></td><td>Cranelift translation and JIT construction</td><td>Frontend or x86-specific MIR</td></tr><tr><td><code>celox-backend-wasm</code></td><td>WebAssembly module generation</td><td>Host runtime behavior</td></tr><tr><td><code>celox-testbench</code></td><td>Source-independent testbench bytecode and values</td><td>Veryl AST traversal or simulator memory ownership</td></tr><tr><td><code>celox-runtime</code></td><td>Events, timed scheduling, VCD output, testbench execution, and backend contracts</td><td>Frontend, SIR optimization, or concrete backend internals</td></tr><tr><td><code>celox</code></td><td>Public API, compilation orchestration, and backend selection</td><td>New reusable compiler algorithms</td></tr></tbody></table><h2 id="phase-artifacts" tabindex="-1">Phase artifacts <a class="header-anchor" href="#phase-artifacts" aria-label="Permalink to &quot;Phase artifacts&quot;">​</a></h2><p>Each major transition consumes an artifact and returns the next one. This keeps phase validity in the type system instead of representing it with optional fields on a shared mutable object.</p><h3 id="symbolicrtl" tabindex="-1"><code>SymbolicRtl</code> <a class="header-anchor" href="#symbolicrtl" aria-label="Permalink to &quot;\`SymbolicRtl\`&quot;">​</a></h3><p>Frontend-owned modules with symbolic combinational and sequential logic. It may contain SLT identities and Veryl-specific lookup information because it has not crossed the frontend boundary yet.</p><h3 id="scheduledrtl" tabindex="-1"><code>ScheduledRtl</code> <a class="header-anchor" href="#scheduledrtl" aria-label="Permalink to &quot;\`ScheduledRtl\`&quot;">​</a></h3><p>The result of flattening hierarchy, assigning source-independent state identities, scheduling logic, and lowering symbolic roots. No downstream component needs the SLT arena to reconstruct runtime behavior.</p><h3 id="unoptimizedsir" tabindex="-1"><code>UnoptimizedSir</code> <a class="header-anchor" href="#unoptimizedsir" aria-label="Permalink to &quot;\`UnoptimizedSir\`&quot;">​</a></h3><p>Backend-independent SIR plus the design and runtime metadata needed by later phases. Physical offsets have not been assigned.</p><h3 id="optimizedsir" tabindex="-1"><code>OptimizedSir</code> <a class="header-anchor" href="#optimizedsir" aria-label="Permalink to &quot;\`OptimizedSir\`&quot;">​</a></h3><p>SIR after the pass manager has applied the selected optimization policy. Only the optimizer transition constructs this artifact, so layout and code generation cannot accidentally consume unoptimized input.</p><h3 id="laidoutprogram" tabindex="-1"><code>LaidOutProgram</code> <a class="header-anchor" href="#laidoutprogram" aria-label="Permalink to &quot;\`LaidOutProgram\`&quot;">​</a></h3><p>Optimized SIR paired with an immutable physical memory layout. All backend-visible state addresses can now be resolved without consulting Veryl source objects.</p><h3 id="runtimeprogram" tabindex="-1"><code>RuntimeProgram</code> <a class="header-anchor" href="#runtimeprogram" aria-label="Permalink to &quot;\`RuntimeProgram\`&quot;">​</a></h3><p>The source-independent metadata retained after code generation: elaborated design metadata, public path lookup, runtime schema, and bound testbench bytecode. A running <code>Simulator</code> stores this artifact beside the executable backend; compiler IR and layout requirements do not remain live during simulation.</p><h2 id="dependency-rules" tabindex="-1">Dependency rules <a class="header-anchor" href="#dependency-rules" aria-label="Permalink to &quot;Dependency rules&quot;">​</a></h2><p>The following rules define the intended architecture:</p><ol><li>Source-language types stop at the frontend boundary.</li><li>Semantic state identities remain distinct from physical memory offsets until layout finalization.</li><li>SIR optimizations are independent of any concrete backend.</li><li>Target MIR, allocation policy, ABI handling, and emission remain private to their backend; target-independent allocation mechanisms belong in <code>celox-backend-common</code>.</li><li>Runtime code depends on backend contracts, not concrete compiler pipelines.</li><li>Testbench execution uses source-independent bytecode; only the frontend parses Veryl testbench syntax.</li><li>The facade coordinates phases but does not become a second owner of their algorithms or data structures.</li></ol><p>These rules are enforced primarily by Cargo dependencies and artifact types. A new dependency that points from a lower layer back toward the facade or frontend is therefore an architectural change, not a convenient shortcut.</p><h2 id="where-changes-belong" tabindex="-1">Where changes belong <a class="header-anchor" href="#where-changes-belong" aria-label="Permalink to &quot;Where changes belong&quot;">​</a></h2><ul><li>A new Veryl construct or source diagnostic belongs in <code>celox-frontend-veryl</code>.</li><li>A symbolic scheduling rule belongs in <code>celox-slt</code>.</li><li>A backend-independent instruction or CFG rule belongs in <code>celox-sir</code>.</li><li>A backend-independent transformation belongs in <code>celox-sir-opt</code>.</li><li>A memory-region or address-placement rule belongs in <code>celox-state-layout</code>.</li><li>A target-independent register-allocation mechanism or constraint data type belongs in <code>celox-backend-common</code>.</li><li>An AArch64 instruction, register constraint, or emission rule belongs in <code>celox-backend-arm64</code>.</li><li>An x86 instruction, register constraint, or emission rule belongs in <code>celox-backend-x86</code>.</li><li>Event ordering, timed execution, or VCD behavior belongs in <code>celox-runtime</code>.</li><li>Public construction options and backend selection belong in the <code>celox</code> facade.</li></ul><p>See <a href="./architecture.html">Simulator Architecture</a> for the end-to-end data flow and <a href="./ir-reference.html">SIR Reference</a> for the backend-independent instruction model.</p>`,35)])])}const u=n(i,[["render",s]]);export{m as __pageData,u as default};
